1	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
2	import {
3	  useListRules, useCreateRule, useUpdateRule, useDeleteRule, useReorderRules,
4	  useAiGenerateRules, useAiEnhanceRule, useConflictCheckRules, getListRulesQueryKey,
5	  useListRuleEntities, useGetProject,
6	  type Rule,
7	} from "@workspace/api-client-react";
8	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
9	import { Button } from "@/components/ui/button";
10	import { Input } from "@/components/ui/input";
11	import { Textarea } from "@/components/ui/textarea";
12	import { Skeleton } from "@/components/ui/skeleton";
13	import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from "@/components/ui/dialog";
14	import { Label } from "@/components/ui/label";
15	import { Badge } from "@/components/ui/badge";
16	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
17	import {
18	  Plus, Edit2, Trash2, Wand2, FileText, Sparkles, Loader2, Copy,
19	  ChevronDown, ChevronRight, Search, Check, X, Info, AlertTriangle,
20	  Lightbulb, RefreshCw, ShieldAlert, GripVertical, Folder,
21	} from "lucide-react";
22	import { useQueryClient } from "@tanstack/react-query";
23	import { useToast } from "@/hooks/use-toast";
24	
25	interface RulesProps {
26	  projectId: number;
27	}
28	
29	const CATEGORIES = ["movement", "combat", "economy", "turn_structure", "variant"] as const;
30	
31	const CATEGORY_META: Record<string, { label: string; bg: string; text: string; border: string; dot: string }> = {
32	  movement:        { label: "Movement",       bg: "bg-blue-500/15",    text: "text-blue-400",    border: "border-blue-500/30",    dot: "bg-blue-400" },
33	  combat:          { label: "Combat",         bg: "bg-red-500/15",     text: "text-red-400",     border: "border-red-500/30",     dot: "bg-red-400" },
34	  economy:         { label: "Economy",        bg: "bg-amber-500/15",   text: "text-amber-400",   border: "border-amber-500/30",   dot: "bg-amber-400" },
35	  turn_structure:  { label: "Turn Structure", bg: "bg-slate-500/15",   text: "text-slate-400",   border: "border-slate-500/30",   dot: "bg-slate-400" },
36	  variant:         { label: "Variant",        bg: "bg-violet-500/15",  text: "text-violet-400",  border: "border-violet-500/30",  dot: "bg-violet-400" },
37	  imported:        { label: "Imported",       bg: "bg-orange-500/15",  text: "text-orange-400",  border: "border-orange-500/30",  dot: "bg-orange-400" },
38	};
39	
40	const catMeta = (cat?: string | null) => {
41	  const key = (cat ?? "").toLowerCase().replace(/\s+/g, "_");
42	  return CATEGORY_META[key] ?? {
43	    label: cat || "uncategorized",
44	    bg: "bg-primary/15",
45	    text: "text-primary",
46	    border: "border-primary/30",
47	    dot: "bg-primary",
48	  };
49	};
50	
51	function PriorityDots({ value }: { value: number }) {
52	  const safe = Math.max(0, Math.min(5, value || 0));
53	  return (
54	    <div className="flex items-center gap-0.5" title={`Priority ${safe}`}>
55	      {[1, 2, 3, 4, 5].map((i) => (
56	        <span
57	          key={i}
58	          className={`h-1.5 w-1.5 rounded-full ${i <= safe ? "bg-primary" : "bg-border"}`}
59	        />
60	      ))}
61	    </div>
62	  );
63	}
64	
65	type AIEnhance = {
66	  rewrittenContent: string;
67	  improvedTitle: string;
68	  designNotes?: string;
69	  edgeCases?: string;
70	  narrativeApplied?: boolean;
71	  relatedRuleSuggestions?: { title: string; content: string; category: string }[];
72	};
73	
74	const COLLAPSE_THRESHOLD = 240;
75	
76	export function Rules({ projectId }: RulesProps) {
77	  const queryClient = useQueryClient();
78	  const { data: rules, isLoading } = useListRules(projectId);
79	  const { data: project } = useGetProject(projectId);
80	  const createRule = useCreateRule();
81	  const updateRule = useUpdateRule();
82	  const deleteRule = useDeleteRule();
83	  const aiGenerate = useAiGenerateRules();
84	  const conflictCheck = useConflictCheckRules();
85	  const { toast } = useToast();
86	
87	  const [duplicatingId, setDuplicatingId] = useState<number | null>(null);
88	  const [expandedIds, setExpandedIds] = useState<Set<number>>(new Set());
89	
90	  const [narrativeRuleIds, setNarrativeRuleIds] = useState<Set<number>>(() => {
91	    try {
92	      const raw = localStorage.getItem(`gameforge:narrative-rule-ids:${projectId}`);
93	      return raw ? new Set(JSON.parse(raw) as number[]) : new Set();
94	    } catch { return new Set(); }
95	  });
96	  const [narrativeEnhanceRuleIds, setNarrativeEnhanceRuleIds] = useState<Set<number>>(() => {
97	    try {
98	      const raw = localStorage.getItem(`gameforge:narrative-enhance-rule-ids:${projectId}`);
99	      return raw ? new Set(JSON.parse(raw) as number[]) : new Set();
100	    } catch { return new Set(); }
101	  });
102	
103	  useEffect(() => {
104	    try { localStorage.setItem(`gameforge:narrative-rule-ids:${projectId}`, JSON.stringify([...narrativeRuleIds])); }
105	    catch { /* quota exceeded – ignore */ }
106	  }, [narrativeRuleIds, projectId]);
107	
108	  useEffect(() => {
109	    try { localStorage.setItem(`gameforge:narrative-enhance-rule-ids:${projectId}`, JSON.stringify([...narrativeEnhanceRuleIds])); }
110	    catch { /* quota exceeded – ignore */ }
111	  }, [narrativeEnhanceRuleIds, projectId]);
112	
113	  const [filter, setFilter] = useState("");
114	  const [categoryFilter, setCategoryFilter] = useState<string>("all");
115	
116	  const [aiPrompt, setAiPrompt] = useState("");
117	  const [isAiOpen, setIsAiOpen] = useState(false);
118	  const [isCreateOpen, setIsCreateOpen] = useState(false);
119	  const [isConflictsOpen, setIsConflictsOpen] = useState(false);
120	  const [conflictReport, setConflictReport] = useState<{
121	    summary: string;
122	    conflicts: Array<{ ruleIds: number[]; severity: string; description: string; suggestion?: string }>;
123	  } | null>(null);
124	  const [editRuleId, setEditRuleId] = useState<number | null>(null);
125	  const [formData, setFormData] = useState({ title: "", content: "", category: "", priority: 0, section: "" });
126	
127	  // Drag-and-drop reorder state
128	  const reorderRules = useReorderRules();
129	  const [draggedId, setDraggedId] = useState<number | null>(null);
130	  const [dropTargetId, setDropTargetId] = useState<number | null>(null);
131	  const [insertBefore, setInsertBefore] = useState<boolean>(true);
132	  const [collapsedSections, setCollapsedSections] = useState<Set<string>>(new Set());
133	  // Track most recent drop intent so we can also patch section on cross-section drag
134	  const dropSectionRef = useRef<string | null>(null);
135	
136	  const errMsg = (err: unknown) => err instanceof Error ? err.message : String(err);
137	
138	  const refresh = () =>
139	    queryClient.invalidateQueries({ queryKey: getListRulesQueryKey(projectId) });
140	
141	  const handleCreate = async () => {
142	    if (!formData.title || !formData.content) return;
143	    try {
144	      // Always send the trimmed section (including ""); the server normalizes empty
145	      // strings to NULL so that users can clear a section back to "Unsectioned".
146	      await createRule.mutateAsync({
147	        projectId,
148	        data: { ...formData, section: formData.section.trim() },
149	      });
150	      setIsCreateOpen(false);
151	      setFormData({ title: "", content: "", category: "", priority: 0, section: "" });
152	      refresh();
153	      toast({ title: "Rule created" });
154	    } catch (err) {
155	      toast({ title: "Could not create rule", description: errMsg(err), variant: "destructive" });
156	    }
157	  };
158	
159	  const handleUpdate = async () => {
160	    if (!editRuleId || !formData.title || !formData.content) return;
161	    try {
162	      await updateRule.mutateAsync({
163	        projectId,
164	        ruleId: editRuleId,
165	        data: { ...formData, section: formData.section.trim() },
166	      });
167	      setEditRuleId(null);
168	      setFormData({ title: "", content: "", category: "", priority: 0, section: "" });
169	      refresh();
170	      toast({ title: "Rule updated" });
171	    } catch (err) {
172	      toast({ title: "Could not update rule", description: errMsg(err), variant: "destructive" });
173	    }
174	  };
175	
176	  const handleDelete = async (id: number) => {
177	    try {
178	      await deleteRule.mutateAsync({ projectId, ruleId: id });
179	      refresh();
180	      toast({ title: "Rule deleted" });
181	    } catch (err) {
182	      toast({ title: "Could not delete rule", description: errMsg(err), variant: "destructive" });
183	    }
184	  };
185	
186	  const handleAiGenerate = async () => {
187	    if (!aiPrompt) return;
188	    try {
189	      const result = await aiGenerate.mutateAsync({ projectId, data: { prompt: aiPrompt, count: 3 } });
190	      setAiPrompt("");
191	      setIsAiOpen(false);
192	      refresh();
193	      if (result.narrativeApplied) {
194	        setNarrativeRuleIds((prev) => new Set([...prev, ...result.items.map((r) => r.id)]));
195	      }
196	      toast({
197	        title: result.narrativeApplied
198	          ? "AI rules generated · Narrative applied"
199	          : "AI rules generated",
200	        description: result.narrativeApplied
201	          ? "Rules are grounded in your game's narrative."
202	          : undefined,
203	      });
204	    } catch (err) {
205	      toast({ title: "AI generate failed", description: errMsg(err), variant: "destructive" });
206	    }
207	  };
208	
209	  const closeForms = () => {
210	    setIsAiOpen(false);
211	    setIsCreateOpen(false);
212	    setEditRuleId(null);
213	    setFormData({ title: "", content: "", category: "", priority: 0, section: "" });
214	  };
215	
216	  const openCreate = () => {
217	    setEditRuleId(null);
218	    setIsAiOpen(false);
219	    setFormData({ title: "", content: "", category: "movement", priority: 1, section: "" });
220	    setIsCreateOpen(true);
221	  };
222	
223	  const openAi = () => {
224	    setIsCreateOpen(false);
225	    setEditRuleId(null);
226	    setIsAiOpen(true);
227	  };
228	
229	  const isFormPanelOpen = isAiOpen || isCreateOpen || editRuleId !== null;
230	
231	  const handleConflictCheck = async () => {
232	    setIsConflictsOpen(true);
233	    setConflictReport(null);
234	    try {
235	      const report = await conflictCheck.mutateAsync({ projectId });
236	      setConflictReport(report);
237	    } catch (err) {
238	      toast({ title: "Conflict check failed", description: errMsg(err), variant: "destructive" });
239	      setIsConflictsOpen(false);
240	    }
241	  };
242	
243	  const handleDuplicate = async (rule: Rule) => {
244	    setDuplicatingId(rule.id);
245	    try {
246	      await createRule.mutateAsync({
247	        projectId,
248	        data: {
249	          title: `${rule.title} (Copy)`,
250	          content: rule.content,
251	          category: rule.category || "",
252	          priority: rule.priority || 0,
253	        },
254	      });
255	      refresh();
256	      toast({ title: "Rule duplicated" });
257	    } catch (err) {
258	      toast({ title: "Duplicate failed", description: errMsg(err), variant: "destructive" });
259	    } finally {
260	      setDuplicatingId(null);
261	    }
262	  };
263	
264	  const openEdit = (rule: Rule) => {
265	    setIsAiOpen(false);
266	    setIsCreateOpen(false);
267	    setFormData({
268	      title: rule.title,
269	      content: rule.content,
270	      category: rule.category || "",
271	      priority: rule.priority || 0,
272	      section: rule.section || "",
273	    });
274	    setEditRuleId(rule.id);
275	  };
276	
277	  const toggleExpand = (id: number) => {
278	    setExpandedIds((prev) => {
279	      const next = new Set(prev);
280	      if (next.has(id)) next.delete(id); else next.add(id);
281	      return next;
282	    });
283	  };
284	
285	  const allCategories = useMemo(() => {
286	    const set = new Set<string>(CATEGORIES);
287	    (rules ?? []).forEach((r) => { if (r.category) set.add(r.category.toLowerCase().replace(/\s+/g, "_")); });
288	    return [...set];
289	  }, [rules]);
290	
291	  const counts = useMemo(() => {
292	    const out: Record<string, number> = {};
293	    (rules ?? []).forEach((r) => {
294	      const key = (r.category ?? "").toLowerCase().replace(/\s+/g, "_") || "uncategorized";
295	      out[key] = (out[key] || 0) + 1;
296	    });
297	    return out;
298	  }, [rules]);
299	
300	  // Server returns rules ordered by display_order ASC, so we preserve that here
301	  // and only apply user filters. Drag-to-reorder is the source of truth for ordering.
302	  const sortedRules = useMemo(() => {
303	    if (!rules) return [];
304	    let list = [...rules].sort((a, b) => {
305	      const ao = a.displayOrder ?? 0;
306	      const bo = b.displayOrder ?? 0;
307	      if (ao !== bo) return ao - bo;
308	      return a.id - b.id;
309	    });
310	    if (categoryFilter !== "all") {
311	      list = list.filter((r) => (r.category ?? "").toLowerCase().replace(/\s+/g, "_") === categoryFilter);
312	    }
313	    if (filter.trim()) {
314	      const q = filter.trim().toLowerCase();
315	      list = list.filter((r) =>
316	        r.title.toLowerCase().includes(q) ||
317	        (r.content || "").toLowerCase().includes(q),
318	      );
319	    }
320	    return list;
321	  }, [rules, filter, categoryFilter]);
322	
323	  // Group rules by section. If no rule has a section, returns a single "" group
324	  // and the UI renders flat (no group headers).
325	  const groupedRules = useMemo(() => {
326	    const groups = new Map<string, Rule[]>();
327	    for (const r of sortedRules) {
328	      const key = (r.section ?? "").trim();
329	      if (!groups.has(key)) groups.set(key, []);
330	      groups.get(key)!.push(r);
331	    }
332	    // Sort: named sections alphabetically first, "" (unsectioned) last
333	    return [...groups.entries()].sort(([a], [b]) => {
334	      if (a === b) return 0;
335	      if (a === "") return 1;
336	      if (b === "") return -1;
337	      return a.localeCompare(b);
338	    });
339	  }, [sortedRules]);
340	
341	  const hasAnySection = useMemo(
342	    () => (rules ?? []).some((r) => r.section && r.section.trim() !== ""),
343	    [rules],
344	  );
345	
346	  const totalRules = rules?.length ?? 0;
347	
348	  // Existing section names (for the section autocomplete in the form)
349	  const existingSections = useMemo(() => {
350	    const set = new Set<string>();
351	    (rules ?? []).forEach((r) => { if (r.section) set.add(r.section.trim()); });
352	    return [...set].sort();
353	  }, [rules]);
354	
355	  const toggleSection = (key: string) => {
356	    setCollapsedSections((prev) => {
357	      const next = new Set(prev);
358	      if (next.has(key)) next.delete(key); else next.add(key);
359	      return next;
360	    });
361	  };
362	
363	  // Map of ruleId -> rule for the auto-linker
364	  const ruleById = useMemo(() => {
365	    const m = new Map<number, Rule>();
366	    (rules ?? []).forEach((r) => m.set(r.id, r));
367	    return m;
368	  }, [rules]);
369	
370	  // Scroll a target rule into view + expand it (used by auto-linker)
371	  const focusRule = useCallback((id: number) => {
372	    setExpandedIds((prev) => {
373	      const next = new Set(prev);
374	      next.add(id);
375	      return next;
376	    });
377	    // Defer scroll until expansion has rendered
378	    requestAnimationFrame(() => {
379	      const el = document.querySelector<HTMLElement>(`[data-rule-id="${id}"]`);
380	      if (el) {
381	        el.scrollIntoView({ behavior: "smooth", block: "center" });
382	        el.classList.add("ring-2", "ring-primary", "ring-offset-2", "ring-offset-background");
383	        setTimeout(() => {
384	          el.classList.remove("ring-2", "ring-primary", "ring-offset-2", "ring-offset-background");
385	        }, 1500);
386	      }
387	    });
388	  }, []);
389	
390	  // ──────────────────────────────────────────────────────────────────────────
391	  // Drag-and-drop reorder
392	  // ──────────────────────────────────────────────────────────────────────────
393	  const handleDragStart = (e: React.DragEvent, ruleId: number) => {
394	    setDraggedId(ruleId);
395	    e.dataTransfer.effectAllowed = "move";
396	    // Some browsers require setData for drag to start
397	    try { e.dataTransfer.setData("text/plain", String(ruleId)); } catch { /* noop */ }
398	  };
399	
400	  const handleDragOver = (e: React.DragEvent, overId: number, sectionKey: string) => {
401	    if (draggedId === null || draggedId === overId) return;
402	    e.preventDefault();
403	    e.dataTransfer.dropEffect = "move";
404	    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
405	    const before = e.clientY - rect.top < rect.height / 2;
406	    setDropTargetId(overId);
407	    setInsertBefore(before);
408	    dropSectionRef.current = sectionKey;
409	  };
410	
411	  const handleDragEnd = () => {
412	    setDraggedId(null);
413	    setDropTargetId(null);
414	    dropSectionRef.current = null;
415	  };
416	
417	  const handleDrop = async () => {
418	    const dragged = draggedId;
419	    const target = dropTargetId;
420	    const before = insertBefore;
421	    const targetSection = dropSectionRef.current;
422	    handleDragEnd();
423	    if (dragged === null || target === null || dragged === target || !rules) return;
424	
425	    const ordered = [...rules].sort((a, b) => {
426	      const ao = a.displayOrder ?? 0;
427	      const bo = b.displayOrder ?? 0;
428	      if (ao !== bo) return ao - bo;
429	      return a.id - b.id;
430	    });
431	    const fromIdx = ordered.findIndex((r) => r.id === dragged);
432	    const toIdx = ordered.findIndex((r) => r.id === target);
433	    if (fromIdx === -1 || toIdx === -1) return;
434	
435	    const [moved] = ordered.splice(fromIdx, 1);
436	    let insertAt = ordered.findIndex((r) => r.id === target);
437	    if (!before) insertAt += 1;
438	    ordered.splice(insertAt, 0, moved);
439	
440	    const ruleIds = ordered.map((r) => r.id);
441	    const draggedRule = rules.find((r) => r.id === dragged);
442	    const sectionChanged =
443	      draggedRule != null &&
444	      targetSection != null &&
445	      (draggedRule.section ?? "") !== targetSection;
446	
447	    try {
448	      // If dropped into a different section, patch the rule's section first
449	      // (empty string -> NULL via server-side normalization).
450	      // Note: this is two sequential mutations; if reorder fails after the section
451	      // patch succeeds, the section change persists but order does not. We refresh
452	      // either way so the UI re-syncs to server truth.
453	      if (sectionChanged) {
454	        await updateRule.mutateAsync({
455	          projectId,
456	          ruleId: dragged,
457	          data: { section: targetSection ?? "" },
458	        });
459	      }
460	      await reorderRules.mutateAsync({ projectId, data: { ruleIds } });
461	      refresh();
462	    } catch (err) {
463	      toast({ title: "Could not reorder", description: errMsg(err), variant: "destructive" });
464	      refresh();
465	    }
466	  };
467	
468	  return (
469	    <div className="space-y-5 pb-8">
470	      {/* Header */}
471	      <div className="flex flex-wrap items-start justify-between gap-3">
472	        <div>
473	          <h2 className="text-2xl font-bold leading-tight">Rules Library</h2>
474	          <p className="text-xs text-muted-foreground mt-1">
475	            {totalRules} {totalRules === 1 ? "rule" : "rules"} · click <span className="text-primary font-medium">AI</span> on any card to enhance
476	          </p>
477	        </div>
478	        <div className="flex items-center gap-2 flex-wrap">
479	          <Button
480	            variant="outline"
481	            onClick={handleConflictCheck}
482	            disabled={conflictCheck.isPending}
483	            className="gap-1.5 border-amber-500/40 text-amber-300 hover:bg-amber-500/10 hover:text-amber-200"
484	            data-testid="rules-conflicts-button"
485	          >
486	            {conflictCheck.isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : <ShieldAlert className="h-4 w-4" />}
487	            Conflicts
488	          </Button>
489	          {!isFormPanelOpen && (
490	            <>
491	              <Button
492	                onClick={openAi}
493	                className="gap-1.5 bg-primary text-primary-foreground hover:bg-primary/90"
494	                data-testid="rules-ai-generate"
495	              >
496	                <Sparkles className="h-4 w-4" /> AI Generate
497	              </Button>
498	              <Button
499	                onClick={openCreate}
500	                className="gap-1.5 bg-primary text-primary-foreground hover:bg-primary/90"
501	                data-testid="rules-add-button"
502	              >
503	                <Plus className="h-4 w-4" /> Add
504	              </Button>
505	            </>
506	          )}
507	        </div>
508	      </div>
509	
510	      {/* Inline AI Generate panel */}
511	      {isAiOpen && (
512	        <Card className="bg-card border-primary/40" data-testid="rules-ai-panel">
513	          <CardHeader className="pb-3 flex flex-row items-center justify-between space-y-0">
514	            <div>
515	              <CardTitle className="text-base">Generate rules with AI</CardTitle>
516	              <p className="text-xs text-muted-foreground mt-1">Describe the kind of rules you want — the AI will draft them using your project's narrative seed as context.</p>
517	            </div>
518	            <Button variant="ghost" size="icon" className="h-8 w-8" onClick={closeForms}><X className="h-4 w-4" /></Button>
519	          </CardHeader>
520	          <CardContent className="space-y-3">
521	            {project?.narrative && (
522	              <div className="rounded-md bg-violet-500/10 border border-violet-500/20 px-3 py-2 text-xs text-violet-300 flex gap-2 items-start">
523	                <Sparkles className="h-3 w-3 mt-0.5 shrink-0 text-violet-400" />
524	                <span className="line-clamp-2 italic">
525	                  {project.narrative.length > 120 ? project.narrative.slice(0, 120) + "…" : project.narrative}
526	                </span>
527	              </div>
528	            )}
529	            <div className="space-y-2">
530	              <Label htmlFor="rules-ai-prompt">What kind of rules?</Label>
531	              <Input
532	                id="rules-ai-prompt"
533	                placeholder="e.g. combat resolution mechanics…"
534	                value={aiPrompt}
535	                onChange={(e) => setAiPrompt(e.target.value)}
536	                onKeyDown={(e) => e.key === "Enter" && handleAiGenerate()}
537	                data-testid="rules-ai-prompt"
538	                autoFocus
539	              />
540	            </div>
541	            <div className="flex justify-end gap-2 pt-2">
542	              <Button variant="outline" onClick={closeForms}>Cancel</Button>
