957	      onUpdated();
958	      toast({ title: "Rewrite applied" });
959	      setTimeout(() => {
960	        setShowEnhance(false);
961	        setApplied(false);
962	        setEnhance(null);
963	      }, 1200);
964	    } catch (err) {
965	      toast({ title: "Apply failed", description: errMsg(err), variant: "destructive" });
966	    } finally {
967	      setApplying(false);
968	    }
969	  };
970	
971	  const handleAddSuggestion = async (s: { title: string; content: string; category: string }, idx: number) => {
972	    setAddingIdx(idx);
973	    try {
974	      await createRule.mutateAsync({
975	        projectId,
