1014	          data-testid={`drag-handle-${rule.id}`}
1015	          aria-label="Drag to reorder rule"
1016	        >
1017	          <GripVertical className="h-4 w-4" />
1018	        </div>
1019	        <button
1020	          className="flex-1 min-w-0 text-left"
1021	          onClick={onToggle}
1022	          data-testid={`expand-rule-${rule.id}`}
1023	        >
1024	          <div className="flex items-center gap-2 flex-wrap">
1025	            {isExpanded
1026	              ? <ChevronDown className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
1027	              : <ChevronRight className="h-3.5 w-3.5 text-muted-foreground shrink-0" />}
1028	            <span className="text-base font-semibold leading-tight text-white">{rule.title}</span>
1029	            <span className={`text-[10px] uppercase font-bold tracking-wider px-1.5 py-0.5 rounded border ${meta.bg} ${meta.text} ${meta.border}`}>
1030	              {meta.label}
1031	            </span>
