1291	// ────────────────────────────────────────────────────────────────────────────
1292	// Auto-link "Rule #N" / "Rule N" / "rule N" references inside content.
1293	// Only links when the referenced rule actually exists in this project.
1294	// ────────────────────────────────────────────────────────────────────────────
1295	const RULE_REF_REGEX = /\b(Rule|rule|RULE)\s*#?\s*(\d+)\b/g;
1296	
1297	function renderRuleContentWithLinks(
1298	  content: string,
1299	  ruleById: Map<number, Rule>,
1300	  onClick: (id: number) => void,
1301	  selfId: number,
1302	): React.ReactNode[] {
1303	  if (!content) return [content];
1304	  const out: React.ReactNode[] = [];
1305	  let lastIndex = 0;
1306	  let match: RegExpExecArray | null;
1307	  RULE_REF_REGEX.lastIndex = 0;
1308	  let key = 0;
1309	  while ((match = RULE_REF_REGEX.exec(content)) !== null) {
1310	    const id = parseInt(match[2], 10);
1311	    const target = ruleById.get(id);
1312	    // Only link if target exists and isn't the same rule (no self-loops)
1313	    if (!target || id === selfId) continue;
1314	    if (match.index > lastIndex) out.push(content.slice(lastIndex, match.index));
1315	    out.push(
1316	      <button
1317	        key={`rl-${key++}-${match.index}`}
1318	        type="button"
1319	        onClick={(e) => { e.stopPropagation(); onClick(id); }}
1320	        className="inline-flex items-center gap-0.5 text-primary hover:text-primary/80 hover:underline font-medium px-0.5 py-0 rounded"
1321	        title={target.title}
1322	        data-testid={`rule-link-${id}`}
1323	      >
1324	        {match[0]}
1325	      </button>,
1326	    );
1327	    lastIndex = match.index + match[0].length;
1328	  }
1329	  if (lastIndex < content.length) out.push(content.slice(lastIndex));
1330	  return out.length > 0 ? out : [content];
1331	}
