36	function parseNoteTopic(raw: string | null | undefined): ParsedTopic {
37	  if (!raw) return { tag: "", links: [] };
38	  try {
39	    const parsed = JSON.parse(raw);
40	    if (typeof parsed === "object" && parsed !== null && !Array.isArray(parsed)) {
41	      return { tag: String(parsed.tag ?? ""), links: Array.isArray(parsed.links) ? parsed.links : [] };
42	    }
43	  } catch {}
44	  return { tag: raw, links: [] };
45	}
