11	interface TurnPoint { turn: number; p10: number; p50: number; p90: number; }
12	interface SimulatorResult {
13	  healthScore: number;
14	  verdict: string;
15	  meanFinal: number;
16	  bankruptRate: number;
17	  turns: TurnPoint[];
18	}
19	
20	export function Simulator({ projectId }: { projectId: number }) {
21	  const { toast } = useToast();
22	  const [iterations, setIterations] = useState(1000);
23	  const [running, setRunning] = useState(false);
24	  const [result, setResult] = useState<SimulatorResult | null>(null);
25	
26	  const [scenario, setScenario] = useState("");
27	  const [logs, setLogs] = useState<string[]>([]);
28	  const [streaming, setStreaming] = useState(false);
29	  const abortRef = useRef<AbortController | null>(null);
30	
31	  const runMonteCarlo = async () => {
32	    setRunning(true); setResult(null);
33	    try {
34	      const base = import.meta.env.BASE_URL.replace(/\/$/, "");
35	      const res = await fetch(`${base}/api/projects/${projectId}/simulator/run`, {
36	        method: "POST", headers: { "Content-Type": "application/json" }, credentials: "include",
37	        body: JSON.stringify({ iterations, turns: 20 }),
38	      });
39	      if (!res.ok) throw new Error("simulation failed");
40	      const data: SimulatorResult = await res.json();
41	      setResult(data);
42	      toast({ title: "Simulation complete", description: `${iterations} iterations.` });
43	    } catch { toast({ title: "Simulation failed", variant: "destructive" }); }
44	    finally { setRunning(false); }
45	  };
46	
47	  const runPlaythrough = async () => {
48	    if (abortRef.current) abortRef.current.abort();
49	    setLogs([]); setStreaming(true);
50	    const ac = new AbortController();
51	    abortRef.current = ac;
52	    try {
53	      const base = import.meta.env.BASE_URL.replace(/\/$/, "");
54	      const res = await fetch(`${base}/api/projects/${projectId}/simulator/playthrough`, {
55	        method: "POST", headers: { "Content-Type": "application/json" }, credentials: "include",
56	        body: JSON.stringify({ focus: scenario || undefined }),
57	        signal: ac.signal,
58	      });
59	      if (!res.ok || !res.body) throw new Error("stream failed");
60	      const reader = res.body.getReader();
61	      const decoder = new TextDecoder();
62	      let buf = "";
63	      let acc = "";
64	      while (true) {
65	        const { value, done } = await reader.read();
66	        if (done) break;
67	        buf += decoder.decode(value, { stream: true });
68	        const events = buf.split("\n\n");
69	        buf = events.pop() || "";
70	        for (const ev of events) {
71	          const dataLine = ev.split("\n").find((l) => l.startsWith("data: "));
72	          if (!dataLine) continue;
73	          try {
74	            const payload = JSON.parse(dataLine.slice(6));
75	            if (payload.done) { setStreaming(false); return; }
76	            if (payload.error) { setLogs(l => [...l, `ERROR: ${payload.error}`]); setStreaming(false); return; }
77	            if (payload.content) {
78	              acc += payload.content;
79	              setLogs([acc]);
80	            }
81	          } catch { /* skip malformed */ }
82	        }
83	      }
84	    } catch (err) {
85	      if ((err as Error).name !== "AbortError") {
86	        toast({ title: "Playthrough failed", variant: "destructive" });
87	      }
88	    } finally { setStreaming(false); }
89	  };
90	
91	  const stopPlaythrough = () => { abortRef.current?.abort(); setStreaming(false); };
92	
93	  useEffect(() => () => { abortRef.current?.abort(); }, []);
94	
95	  return (
96	    <div className="space-y-6 max-w-5xl">
97	      <div>
98	        <h2 className="text-2xl font-bold flex items-center gap-2"><Dice5 className="h-6 w-6 text-primary" /> Simulator</h2>
99	        <p className="text-muted-foreground text-sm mt-1">Stress-test your design with Monte Carlo runs and AI playthroughs.</p>
100	      </div>
101	
102	      <Tabs defaultValue="montecarlo">
103	        <TabsList>
104	          <TabsTrigger value="montecarlo" className="gap-2"><Activity className="h-4 w-4" /> Monte Carlo</TabsTrigger>
105	          <TabsTrigger value="playthrough" className="gap-2"><Sparkles className="h-4 w-4" /> AI Playthrough</TabsTrigger>
106	        </TabsList>
107	
108	        <TabsContent value="montecarlo" className="space-y-4 mt-4">
109	          <Card>
110	            <CardHeader>
111	              <CardTitle>Run a Monte Carlo simulation</CardTitle>
112	              <CardDescription>Replays many random games to estimate health, balance, and bankruptcy risk.</CardDescription>
113	            </CardHeader>
114	            <CardContent className="space-y-4">
115	              <div className="flex items-end gap-3">
116	                <div className="space-y-2 max-w-[180px]">
117	                  <Label>Iterations</Label>
118	                  <Input type="number" min={100} max={10000} step={100} value={iterations} onChange={e => setIterations(parseInt(e.target.value) || 1000)} />
119	                </div>
120	                <Button onClick={runMonteCarlo} disabled={running} className="gap-2">
121	                  <Play className="h-4 w-4" /> {running ? "Running..." : "Run"}
122	                </Button>
123	              </div>
124	              {result && (
125	                <div className="space-y-4">
126	                  <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
127	                    <Stat label="Health" value={`${result.healthScore.toFixed(1)}/100`} />
128	                    <Stat label="Mean final" value={result.meanFinal.toFixed(2)} />
129	                    <Stat label="Bankrupt rate" value={`${(result.bankruptRate * 100).toFixed(1)}%`} />
130	                    <Stat label="Turns sampled" value={String(result.turns.length)} />
131	                  </div>
132	                  <div className="p-4 rounded-lg border border-border bg-muted/20">
133	                    <div className="text-sm font-medium">Verdict</div>
134	                    <div className="text-sm text-muted-foreground mt-1">{result.verdict}</div>
135	                  </div>
136	                  {result.turns.length > 0 && (
137	                    <div>
138	                      <div className="text-sm font-semibold mb-2">Turn-by-turn (P10 / P50 / P90)</div>
139	                      <div className="space-y-1 max-h-64 overflow-y-auto pr-2">
140	                        {result.turns.map(t => (
141	                          <div key={t.turn} className="grid grid-cols-4 gap-2 text-xs font-mono items-center">
142	                            <div className="text-muted-foreground">Turn {t.turn}</div>
143	                            <div>P10: {t.p10}</div>
144	                            <div>P50: <span className="font-bold">{t.p50}</span></div>
145	                            <div>P90: {t.p90}</div>
146	                          </div>
147	                        ))}
148	                      </div>
149	                    </div>
150	                  )}
151	                </div>
152	              )}
153	            </CardContent>
154	          </Card>
155	        </TabsContent>
156	
157	        <TabsContent value="playthrough" className="space-y-4 mt-4">
158	          <Card>
159	            <CardHeader>
160	              <CardTitle>AI playthrough</CardTitle>
161	              <CardDescription>Stream a turn-by-turn dramatized walkthrough of one game.</CardDescription>
162	            </CardHeader>
163	            <CardContent className="space-y-4">
164	              <div className="space-y-2">
165	                <Label>Optional focus</Label>
166	                <Textarea rows={2} value={scenario} onChange={e => setScenario(e.target.value)} placeholder="aggressive playstyle, edge cases..." />
167	              </div>
168	              <div className="flex gap-2">
169	                {!streaming ? (
170	                  <Button onClick={runPlaythrough} className="gap-2"><Play className="h-4 w-4" /> Start playthrough</Button>
171	                ) : (
172	                  <Button onClick={stopPlaythrough} variant="destructive" className="gap-2"><Square className="h-4 w-4" /> Stop</Button>
173	                )}
174	              </div>
175	              <div className="bg-muted/30 border border-border rounded-lg p-4 max-h-[500px] overflow-y-auto text-sm">
176	                {logs.length === 0 && !streaming && <div className="text-muted-foreground italic">No playthrough yet.</div>}
177	                {logs.map((l, i) => <div key={i} className="whitespace-pre-wrap">{l}</div>)}
178	                {streaming && <div className="text-primary animate-pulse mt-2">▍</div>}
179	              </div>
180	            </CardContent>
181	          </Card>
182	        </TabsContent>
183	      </Tabs>
184	    </div>
185	  );
186	}
187	
188	function Stat({ label, value }: { label: string; value: string }) {
189	  return (
190	    <div className="p-3 rounded-lg border border-border bg-card">
191	      <div className="text-xs uppercase tracking-wider text-muted-foreground">{label}</div>
192	      <div className="text-lg font-bold mt-1">{value}</div>
193	    </div>
194	  );
195	}
