70	function parseStats(raw: string | null | undefined): { key: string; val: string }[] {
71	  if (!raw) return [];
72	  return raw
73	    .split(/[/\n]/)
74	    .map((s) => s.trim())
75	    .filter(Boolean)
76	    .map((s) => {
77	      const m = s.match(/^([^:=0-9]+?)\s*[:=]?\s*(\S+)\s*$/);
78	      if (m) return { key: m[1].trim(), val: m[2] };
79	      const n = s.match(/^([\D]+?)\s*(\d[\d.]*)\s*$/);
80	      if (n) return { key: n[1].trim(), val: n[2] };
81	      return { key: s, val: "" };
82	    });
83	}
84	
85	function serializeStats(pairs: { key: string; val: string }[]): string {
86	  return pairs
87	    .filter((p) => p.key.trim())
88	    .map((p) => (p.val ? `${p.key} ${p.val}` : p.key))
89	    .join(" / ");
90	}
